// COMPONENTE ASIGNATURA

const Asignatura = (props) => {

    const listaDificultades = DIFICULTADES.map(dificultad => {

        let idCheckbox =
            "check-" +
            props.posAlumno + "-" +
            props.posAsignatura + "-" +
            dificultad.id;

        return (

            <FormGroup check key={dificultad.id}>

                <Input
                    id={idCheckbox}
                    type="checkbox"
                    checked={
                        props.asignatura.dificultades.includes(
                            dificultad.id
                        )
                    }
                    onChange={() =>
                        props.cambiarDificultad(
                            props.posAlumno,
                            props.posAsignatura,
                            dificultad.id
                        )
                    }
                />

                <Label check for={idCheckbox}>

                    <strong>{dificultad.nombre}: </strong>

                    {dificultad.descripcion}

                </Label>

            </FormGroup>

        );
    });

    return (

        <div className="col-md-6 col-lg-4 mb-3">

            <Card className="h-100">

                <CardHeader className="bg-primary text-white">

                    <h3>{props.asignatura.nombre}</h3>

                </CardHeader>

                <CardBody>

                    <h5>Dificultades detectadas:</h5>

                    {listaDificultades}

                    <FormGroup className="mt-3">

                        <Label>
                            <strong>Otros:</strong>
                        </Label>

                        <Input
                            type="textarea"
                            placeholder="Introduzca otras observaciones..."
                            value={props.asignatura.otros}
                            onChange={(event) =>
                                props.cambiarOtros(
                                    props.posAlumno,
                                    props.posAsignatura,
                                    event.target.value
                                )
                            }
                        />

                    </FormGroup>

                </CardBody>

            </Card>

        </div>

    );
};


// COMPONENTE INFORME

const Informe = (props) => {

    const listaAsignaturas = props.asignaturas.map(
        (asignatura, posAsignatura) => {

            const listaAlumnos = props.cuestionario.map(
                (alumno, posAlumno) => {

                    let datosAsignatura =
                        alumno.asignaturas[posAsignatura];

                    let dificultadesSeleccionadas =
                        DIFICULTADES.filter(dificultad =>
                            datosAsignatura.dificultades.includes(
                                dificultad.id
                            )
                        );

                    let listaDificultades =
                        dificultadesSeleccionadas.map(dificultad =>

                            <li key={dificultad.id}>

                                <strong>
                                    {dificultad.nombre}:
                                </strong>

                                {" " + dificultad.descripcion}

                            </li>

                        );

                    return (

                        <Card
                            key={posAlumno}
                            className="mb-3"
                        >

                            <CardHeader>

                                <h3>{alumno.nombre}</h3>

                            </CardHeader>

                            <CardBody>

                                <h5>Dificultades detectadas:</h5>

                                {
                                    listaDificultades.length > 0 ?

                                        <ul>
                                            {listaDificultades}
                                        </ul>

                                        :

                                        <p>
                                            No se han indicado dificultades.
                                        </p>
                                }

                                <h5>Otros:</h5>

                                <p>
                                    {
                                        datosAsignatura.otros.trim() !== "" ?

                                            datosAsignatura.otros

                                            :

                                            "Sin observaciones adicionales."
                                    }
                                </p>

                            </CardBody>

                        </Card>

                    );
                }
            );

            return (

                <div key={posAsignatura} className="mt-4">

                    <h2 className="bg-primary text-white p-3">

                        {asignatura}

                    </h2>

                    {listaAlumnos}

                </div>

            );
        }
    );

    return (

        <div className="container">

            <h1 className="text-center mt-3">
                INFORME GENERAL POR ASIGNATURAS
            </h1>

            {listaAsignaturas}

            <Button
                color="secondary"
                className="my-3 me-3"
                onClick={props.volverCuestionario}
            >
                VOLVER AL CUESTIONARIO
            </Button>

            <Button
                color="primary"
                className="my-3"
                onClick={() => window.print()}
            >
                IMPRIMIR INFORME
            </Button>

        </div>

    );
};


// COMPONENTE PRINCIPAL APP

class App extends Component {

    constructor(props) {

        super(props);

        this.state = {
            displayFormulario: true,
            informe: false,
            alumnos: undefined,
            asignaturas: undefined,
            cuestionario: [],
            error: ""
        };
    }


    toggleModal() {

        this.setState(estadoAnterior => ({
            displayFormulario: !estadoAnterior.displayFormulario,
            error: ""
        }));

    }


    setFormulario(alu, asig) {

        try {

            let alumnos = JSON.parse(alu);
            let asignaturas = JSON.parse(asig);

            // Comprobamos que los datos sean arrays de nombres.

            if (
                !Array.isArray(alumnos) ||
                !Array.isArray(asignaturas) ||
                alumnos.length === 0 ||
                asignaturas.length === 0 ||
                !alumnos.every(alumno =>
                    typeof alumno === "string" &&
                    alumno.trim() !== ""
                ) ||
                !asignaturas.every(asignatura =>
                    typeof asignatura === "string" &&
                    asignatura.trim() !== ""
                )
            ) {
                throw new Error("Formato incorrecto.");
            }

            // Creamos todas las combinaciones de alumnos
            // y asignaturas.

            let cuestionario = alumnos.map(alumno => ({

                nombre: alumno,

                asignaturas: asignaturas.map(asignatura => ({

                    nombre: asignatura,
                    dificultades: [],
                    otros: ""

                }))

            }));

            this.setState({
                alumnos: alumnos,
                asignaturas: asignaturas,
                cuestionario: cuestionario,
                displayFormulario: false,
                informe: false,
                error: ""
            });

        } catch (error) {

            this.setState({
                error: 'Introduce los datos en formato JSON. Ejemplo: ["Ana", "Pablo"]'
            });

        }
    }


    cambiarDificultad(posAlumno, posAsignatura, idDificultad) {

        this.setState(estadoAnterior => {

            // 1. Hacemos una copia del cuestionario.

            let cuestionario = JSON.parse(
                JSON.stringify(estadoAnterior.cuestionario)
            );

            let dificultades =
                cuestionario[posAlumno]
                    .asignaturas[posAsignatura]
                    .dificultades;

            // 2. Modificamos la copia.

            if (dificultades.includes(idDificultad)) {

                cuestionario[posAlumno]
                    .asignaturas[posAsignatura]
                    .dificultades = dificultades.filter(
                        dificultad => dificultad !== idDificultad
                    );

            } else {

                dificultades.push(idDificultad);

            }

            // 3. Actualizamos el estado.

            return {
                cuestionario: cuestionario
            };

        });
    }


    cambiarOtros(posAlumno, posAsignatura, texto) {

        this.setState(estadoAnterior => {

            // 1. Hacemos una copia.

            let cuestionario = JSON.parse(
                JSON.stringify(estadoAnterior.cuestionario)
            );

            // 2. Modificamos la copia.

            cuestionario[posAlumno]
                .asignaturas[posAsignatura]
                .otros = texto;

            // 3. Actualizamos el estado.

            return {
                cuestionario: cuestionario
            };

        });
    }


    generarInforme() {

        this.setState({
            informe: true
        });

    }


    volverCuestionario() {

        this.setState({
            informe: false
        });

    }


    render() {

        let mostrarComponentes;

        if (this.state.displayFormulario) {

            mostrarComponentes =

                <Formulario
                    mostrar={this.state.displayFormulario}
                    toggleModal={this.toggleModal.bind(this)}
                    setFormulario={this.setFormulario.bind(this)}
                    error={this.state.error}
                />;

        } else if (this.state.informe) {

            mostrarComponentes =

                <Informe
                    cuestionario={this.state.cuestionario}
                    asignaturas={this.state.asignaturas}
                    volverCuestionario={
                        this.volverCuestionario.bind(this)
                    }
                />;

        } else if (this.state.cuestionario.length > 0) {

            mostrarComponentes =

                <Cuestionario
                    cuestionario={this.state.cuestionario}
                    cambiarDificultad={
                        this.cambiarDificultad.bind(this)
                    }
                    cambiarOtros={
                        this.cambiarOtros.bind(this)
                    }
                    generarInforme={
                        this.generarInforme.bind(this)
                    }
                />;

        } else {

            mostrarComponentes =

                <Button
                    color="primary"
                    onClick={this.toggleModal.bind(this)}
                >
                    INTRODUCIR ALUMNOS Y ASIGNATURAS
                </Button>;

        }

        return (

            <div className="App">

                {mostrarComponentes}

            </div>

        );
    }
}

export default App;
